{
using(var sr = new StreamReader(File.Open("test.txt", FileMode.Open)))
{
return await sr.ReadToEndAsync();
}
}
static string ReadFileSync1()
{
Task.Delay(2000).Wait();
return "content1";
}
static string ReadFileSync2()
{
